//! 🧫️ Original payload identity and independent serde output survive completion, foreign callers and cancellation.
use super::*;
use semio_framework_os_spr as protocol;
use semio_framework_os_store_operation_wire::{OriginalReplacementReceiving,ArtifactOperationWire};
use semio_framework_value::{RetainedCloneGrant,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_job::{OriginalTurnFailure,close_original_retained_step};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner};
#[global_allocator]
static ALLOCATOR:semio_framework_trace_memory_testing::RequestedAllocator=semio_framework_trace_memory_testing::RequestedAllocator;
pub(crate) fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:256}}
pub(crate) fn source_stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1_000_000,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,..stock()}}
pub(crate) fn clock()->Option<u64>{Some(1)}
pub(crate) fn turn<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{
 let before=caller.cumulative_receipt();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(stock(),decoder,run));let value=result.unwrap();let after=caller.cumulative_receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));value
}
fn schedule(cutoff:Option<usize>){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let payload=law["wire"].as_str().unwrap().as_bytes().to_vec();let pointer=payload.as_ptr();let length=payload.len();let mut row=protocol::EffectiveSupersession{transition_id:"original-transition".into(),actor:"original-actor".into(),timestamp:protocol::HybridLogicalTimestamp::new(0,0),scope:None,replacement:protocol::InputReplacement::Input{schema:law["schema"].as_str().unwrap().into(),payload}};
 let codec=ArtifactOperationWire::<Vec<String>>::canonical().with_original_receiving();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(semio_framework_value::factory::OwnedValueRetirementFactory::<Vec<String>>::default());let mut owner=OriginalReplacementReceiving::default();let mut caller=OriginalJobFixtureCaller::admit(OperationId(991),Generation(17),source_stock(),clock,u64::MAX,16*1024*1024);let mut decoder=OriginalJobDecodeOwner::empty();let mut ready=false;
 for step in 0..100000{if cutoff==Some(step){break}ready=turn(&mut caller,&mut decoder,|cx|owner.advance(&mut row.replacement,&codec,&factory,cx));if owner.retains_source(){let mut foreign_recipient=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();turn(&mut caller,&mut decoder,|cx|{let grant=cx.retained_grant();let refused=cx.with_native_receiving(|control|control.with_retirement_owner(0,|control|(control.with_retirement_child(&mut foreign_recipient,|foreign|owner.advance_native(&mut row.replacement,&codec,&factory,foreign,grant)),None)));assert_eq!(refused.unwrap_err().kind,ValueRefusalKind::InvariantViolated);Ok(())});let mut foreign=OriginalJobFixtureCaller::admit(OperationId(991),Generation(17),source_stock(),clock,u64::MAX,16*1024*1024);let mut foreign_decoder=OriginalJobDecodeOwner::empty();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn_with_decoder(stock(),&mut foreign_decoder,|cx|owner.advance(&mut row.replacement,&codec,&factory,cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));while !foreign_decoder.terminal_is_empty(){foreign.turn(stock(),|cx|cx.with_original_retirement(|cx|{let d=foreign_decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|foreign_decoder.close_step(g))?;Ok(())})).unwrap();}foreign.retire(stock());}if ready{break}}
 if cutoff.is_none(){assert!(ready);let mut output=None;turn(&mut caller,&mut decoder,|cx|owner.take_input(&mut output,cx));let mut output=output.unwrap();assert_eq!(serde_json::to_value(output.borrow().unwrap().get()).unwrap(),law["value"]);while !output.terminal_is_empty(){turn(&mut caller,&mut decoder,|cx|close_original_retained_step(cx,output.close_demand(cx.retained_grant().maximum_copy_bytes)?,|g|output.close_step(g)).map(|_|()));}}
 owner.begin_close();for _ in 0..100000{if turn(&mut caller,&mut decoder,|cx|owner.close(&mut row.replacement,cx)){break}}assert!(owner.terminal_is_empty());let protocol::InputReplacement::Input{payload,..}=&row.replacement else{panic!("original input variant")};assert_eq!((payload.as_ptr(),payload.len()),(pointer,length));assert_eq!(std::str::from_utf8(payload).unwrap(),law["wire"].as_str().unwrap());drop(owner);
 let mut original=ControlledRetirement::new(row).ok().unwrap();while !original.terminal_is_empty(){turn(&mut caller,&mut decoder,|cx|close_original_retained_step(cx,original.next_demand(cx.retained_grant().maximum_copy_bytes)?,|g|original.step(g)).map(|_|()));}let mut issuer=semio_framework_value::FactoryAuthority::new(factory);while !issuer.terminal_is_empty(){turn(&mut caller,&mut decoder,|cx|close_original_retained_step(cx,issuer.demands(cx.retained_grant().maximum_copy_bytes)?,|g|issuer.step(g)).map(|_|()));}
 for _ in 0..100000{if decoder.terminal_is_empty(){break}caller.turn(stock(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}assert!(decoder.terminal_is_empty());caller.retire(stock());
}
#[test]
fn native_replacement_restores_same_payload_and_preserves_original_receipts_at_every_close(){schedule(None);let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for cutoff in law["cancelPrefixes"].as_array().unwrap(){schedule(Some(cutoff.as_u64().unwrap()as usize));}}
